    (\hat{S}_{[\eval_{u}(\cdot_{W}) = a]})_{\bob \bob'} &\simeq_{\delta_S} (\hat{M}^{(\Point, W), u}_{a})_{\alice \bob''} \label{eq:qld-s-point-con-bob},
